export function getLocale(language) {
  return language === 'en' ? 'en' : 'zh-TW';
}

export function documentShell(language) {
  const locale = getLocale(language);
  return {
    lang: locale === 'en' ? 'en' : 'zh-Hant-TW',
    title: messages[locale].appName,
    description: messages[locale].documentDescription,
    manifest: locale === 'en' ? './manifest.en.webmanifest' : './manifest.webmanifest',
  };
}

export function t(language, key, vars = {}) {
  const locale = getLocale(language);
  const value = messages[locale][key] ?? key;
  return String(value).replace(/\{(\w+)\}/g, (_, name) => String(vars[name] ?? `{${name}}`));
}

export function formatDate(language, iso, options = {}) {
  if (!iso) return t(language, 'noDate');
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return t(language, 'noDate');
  return new Intl.DateTimeFormat(getLocale(language), { dateStyle: 'medium', ...options }).format(date);
}

export function formatDateTime(language, iso) {
  if (!iso) return t(language, 'noDate');
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return t(language, 'noDate');
  return new Intl.DateTimeFormat(getLocale(language), { dateStyle: 'medium', timeStyle: 'short' }).format(date);
}

function dayKey(value) {
  const date = new Date(value);
  return `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
}

export function relativeDueText(language, iso, now = new Date()) {
  if (!iso) return t(language, 'noDeadline');
  const target = new Date(iso);
  if (Number.isNaN(target.getTime())) return t(language, 'noDate');
  const today = new Date(now);
  today.setHours(0, 0, 0, 0);
  const targetDay = new Date(target);
  targetDay.setHours(0, 0, 0, 0);
  const diff = Math.round((targetDay.getTime() - today.getTime()) / 86400000);
  if (dayKey(targetDay) === dayKey(today)) return t(language, 'today');
  if (diff === 1) return t(language, 'tomorrow');
  if (diff < 0) return t(language, 'overdueDays', { count: Math.abs(diff) });
  if (diff <= 7) return t(language, 'inDays', { count: diff });
  return formatDate(language, iso);
}

export function currentLocale(language) {
  return getLocale(language);
}

export function isKnownLocale(language) {
  return language === 'en' || language === 'zh-TW';
}
